37|export function formatTimestamp(date = new Date()) {
38|	const pad = (n) => String(n).padStart(2, "0");
39|	const yyyy = date.getFullYear();
40|	const MM = pad(date.getMonth() + 1);
41|	const dd = pad(date.getDate());
42|	const hh = pad(date.getHours());
43|	const mm = pad(date.getMinutes());
44|	const ss = pad(date.getSeconds());
45|	return `${yyyy}${MM}${dd}-${hh}${mm}${ss}`;
