1069|			}
1070|		} else if (previousReports.length > 0) {
1071|			const reportList = previousReports
1072|				.map((p) =>
1073|					typeof p === "string" ? p : p.path || p.filename || p.stageSlug,
1074|				)
1075|				.filter(Boolean)
