1256|/***
1257| * MARK: renderStageVerdictGuidance
1258| * @description Resolves the "# Stage Failure Guidance" body: the
1259| *   `stage-verdict` skill body (project overlay wins via the skill loader)
1260| *   for agent stages — unless the stage already attaches it (injected in 2b,
1261| *   never duplicate) — with a legacy one-liner fallback when the skill is
1262| *   missing or invalid.
1263| * @example renderStageVerdictGuidance({ stage: { type: "agent" }, skillLoader: () => null, fallback: "legacy" }) => "legacy"
1264| * @param {Object} [opts]
1265| * @param {Object} [opts.stage] - The current stage definition.
1266| * @param {Function} [opts.skillLoader] - (name) => skill descriptor | null.
1267| * @param {Array} [opts.stageSkillAttachments] - The stage.skills attachments.
1268| * @param {string} [opts.fallback] - Legacy text when the skill is unavailable.
1269| * @returns {string} The guidance body.
1270| ***/
1271|export function renderStageVerdictGuidance({
1272|	stage,
1273|	skillLoader,
1274|	stageSkillAttachments = [],
1275|	fallback = "",
1276|}) {
1277|	if (!stageExpectsAgentVerdict(stage)) return fallback;
1278|	const attached = (
1279|		Array.isArray(stageSkillAttachments) ? stageSkillAttachments : []
1280|	).some(
1281|		(attachment) =>
1282|			attachment &&
1283|			typeof attachment === "object" &&
1284|			String(attachment.name || "").trim().toLowerCase() ===
1285|				"stage-verdict",
1286|	);
1287|	if (attached) return fallback;
1288|	try {
1289|		const skill = skillLoader?.("stage-verdict");
1290|		if (
1291|			skill &&
1292|			!skill.invalid &&
1293|			typeof skill.body === "string" &&
1294|			skill.body.trim()
1295|		) {
1296|			return skill.body.trim();
1297|		}
1298|	} catch {
1299|		// Fall through to the legacy text below.
1300|	}
1301|	return fallback;
1302|}
