1304|/***
1305| * MARK: buildNoCodePromptSection
1306| * @description Pure helper building the docs-only instruction block injected into
1307| *   an agent prompt when a stage is marked `noCode`. The docs directory name
1308| *   honours the project's resolved link folder (falls back to `docs`).
1309| * @example buildNoCodePromptSection('docs').includes('docs') => true
1310| * @param {string|Object} [docsDirName] - Docs folder name or project carrying it.
1311| * @returns {string} Markdown block.
1312| ***/
1313|export function buildNoCodePromptSection(docsDirName) {
1314|	let dir = docsDirName;
1315|	if (dir && typeof dir === "object") {
1316|		dir = resolveDocsDirName(dir);
1317|	}
1318|	if (typeof dir !== "string" || !dir.trim()) {
1319|		dir = "docs";
1320|	} else {
1321|		dir = dir.trim();
1322|	}
1323|	return [
1324|		"# No Code (Docs-Only)",
1325|		`This stage is marked no-code (docs-only). You may read and search the entire repository for context,`,
1326|		`but you must ONLY create or modify files under \`./${dir}/\` (in particular this task's docs folder).`,
1327|		`Do not edit source code, configuration, tests, or any file outside the documentation directory.`,
1328|		`Any code changes you make outside \`./${dir}/\` will be discarded by the engine and will not be committed.`,
1329|	].join("\n");
