			projectName: project?.name || project?.id || "",
			projectRepo: project?.gitUrl || project?.repoUrl || null,
			projectCwd: project?.cwd || "",
			reports: Array.isArray(task?.reports) ? task.reports : [],
			failureDetails,
		});
