16|/***
17| * MARK: listTaskDocsFiles
18| * @description Lists the top-level files actually present in a task's docs
19| *   folder (`<projectCwd>/<docsDirName>/tasks/<taskId>/`), newest first
20| *   (mtime descending, filename ascending tiebreak) — the disk-authoritative
21| *   source for the `# Previous Reports` prompt section. `task.md` (the
22| *   task's own metadata file) and subdirectories are excluded; every other
23| *   extension is included, including links that resolve to a regular file.
24| *   How it can fail: a missing or unreadable folder yields
25| *   `{ files: [], dirExists: false }`; a taskId that escapes the tasks root
26| *   is rejected the same way; an entry that cannot be stat'ed (deleted
27| *   mid-read, broken link) is omitted rather than listed with a zero time,
28| *   so the prompt never names a file the agent cannot open. Never throws.
29| * @example listTaskDocsFiles('/repo', 'task-1').files => [{ filename: 'SURVEY.md', path: './docs/tasks/task-1/SURVEY.md', mtimeMs: 123 }]
30| * @param {string} projectCwd - Absolute project working directory.
31| * @param {string} taskId - Task id (also the folder's final segment).
32| * @param {Object|string} [docsProject] - Project record (or bare folder name) carrying `docsDirName`.
33| * @returns {{files: Array<{filename: string, path: string, mtimeMs: number}>, dirExists: boolean, docsDirName: string}}
34| ***/
35|export const listTaskDocsFiles = (projectCwd, taskId, docsProject) => {
36|	const docsProjectRecord =
37|		typeof docsProject === "string" ? { docsDirName: docsProject } : docsProject;
38|	const docsDirName = resolveDocsDirName(docsProjectRecord);
39|	if (!projectCwd || !taskId || typeof taskId !== "string") {
40|		return { files: [], dirExists: false, docsDirName };
41|	}
42|	const taskDocsDir = resolveTaskDocsDir(projectCwd, docsProjectRecord, taskId);
43|	const tasksRoot = resolveTasksDir(projectCwd, docsProjectRecord);
44|	if (
45|		!taskDocsDir ||
46|		!tasksRoot ||
47|		path.basename(taskDocsDir) !== taskId ||
48|		path.relative(tasksRoot, taskDocsDir).startsWith("..")
49|	) {
50|		return { files: [], dirExists: false, docsDirName };
51|	}
52|	/* eslint-disable security/detect-non-literal-fs-filename */
53|	try {
54|		if (!fs.existsSync(taskDocsDir)) return { files: [], dirExists: false, docsDirName };
55|		const entries = fs.readdirSync(taskDocsDir, { withFileTypes: true });
56|		const files = [];
57|		for (const entry of entries) {
58|			if (entry.name === "task.md") continue;
59|			if (!entry.isFile() && !entry.isSymbolicLink()) continue;
60|			let entryStat = null;
61|			try {
62|				entryStat = fs.statSync(path.join(taskDocsDir, entry.name));
63|			} catch {
64|				entryStat = null;
65|			}
66|			// Fail closed: an entry that cannot be stat'ed (or that is not a
67|			// regular file once links are followed) is omitted. Listing it
68|			// would reintroduce the phantom-file problem this module exists
69|			// to fix: every named file must open successfully.
70|			if (!entryStat || !entryStat.isFile()) continue;
71|			files.push({
72|				filename: entry.name,
73|				path: `./${docsDirName}/tasks/${taskId}/${entry.name}`,
74|				mtimeMs: entryStat.mtimeMs || 0,
75|			});
76|		}
77|		files.sort((a, b) => {
78|			if (b.mtimeMs !== a.mtimeMs) return b.mtimeMs - a.mtimeMs;
79|			return String(a.filename).localeCompare(String(b.filename));
80|		});
81|		return { files, dirExists: true, docsDirName };
82|	} catch {
83|		return { files: [], dirExists: false, docsDirName };
84|	}
85|	/* eslint-enable security/detect-non-literal-fs-filename */
86|};

