221| * @description Renders a timeline entry's per-stage diff size as the optional
222| *   4th markdown segment (`+N -M`). Returns an empty string when the entry
223| *   carries no diff data, so legacy entries write exactly as before.
224| * @example formatTimelineDiffStat({ additions: 12, deletions: 3 }) => '+12 -3'
225| * @example formatTimelineDiffStat({ stage: 'Idea' }) => ''
226| * @param {Object} [entry] - Timeline entry.
227| * @returns {string} Diff segment, or '' when absent.
228| ***/
229|export function formatTimelineDiffStat(entry) {
230|	if (
231|		!entry ||
232|		!Number.isInteger(entry.additions) ||
233|		!Number.isInteger(entry.deletions) ||
234|		entry.additions < 0 ||
235|		entry.deletions < 0
236|	) {
237|		return "";
238|	}
239|	return `+${entry.additions} -${entry.deletions}`;
