242|/***
243| * MARK: parseTimelineDiffStat
244| * @description Reads the optional 4th timeline segment (`+N -M`) back into
245| *   addition/deletion counts. Legacy 3-segment lines (undefined segment) and
246| *   malformed segments resolve to null and are ignored by the caller.
247| * @example parseTimelineDiffStat('+12 -3') => { additions: 12, deletions: 3 }
248| * @example parseTimelineDiffStat(undefined) => null
249| * @param {string} [segment] - Raw 4th `|` segment.
250| * @returns {{ additions: number, deletions: number }|null} Counts, or null.
251| ***/
252|export function parseTimelineDiffStat(segment) {
253|	if (typeof segment !== "string") return null;
254|	const match = segment.trim().match(/^\+(\d+)\s*-\s*(\d+)$/);
255|	if (!match) return null;
256|	return {
257|		additions: Number.parseInt(match[1], 10),
258|		deletions: Number.parseInt(match[2], 10),
