320|export function _entryBoundary(entry) {
321|	let start = null;
322|	let end = null;
323|	if (entry) {
324|		const startCandidates = ["boundaryStartSha", "baseSha"];
325|		const endCandidates = ["boundaryEndSha", "headSha"];
326|		for (const key of startCandidates) {
327|			const value = entry[key];
328|			if (typeof value === "string" && value.trim()) {
329|				start = value.trim();
330|				break;
331|			}
332|		}
333|		for (const key of endCandidates) {
334|			const value = entry[key];
335|			if (typeof value === "string" && value.trim()) {
336|				end = value.trim();
337|				break;
338|			}
339|		}
340|	}
341|	return { start, end };
