692|/***
693| * MARK: hashPromptLayout
694| * @description Short non-crypto fingerprint of a layout for fallback logs
695| *   (identifies WHICH bad layout served default without logging its body).
696| * @example hashPromptLayout('{{task}}').length => 8
697| * @param {string} layout - Layout markdown.
698| * @returns {string} Eight hex chars.
699| ***/
700|export function hashPromptLayout(layout) {
701|	let hash = 0;
702|	for (const char of String(layout ?? "")) {
703|		hash = (hash * 31 + char.charCodeAt(0)) >>> 0;
704|	}
705|	return hash.toString(16).padStart(8, "0");
