757|/***
758| * MARK: renderCustomLayoutChunk
759| * @description Renders one blank-line-delimited layout chunk: section tokens
760| *   substitute their pre-built blocks raw (never re-interpolated, so legacy
761| *   bodies keep byte-identical text), while the surrounding custom prose is
762| *   interpolated with the live keyword context.
763| * @param {string} chunk - One layout chunk.
764| * @param {Object} [sectionMap] - Section name to pre-built block text.
765| * @param {Object} [interpolationContext] - Live keyword context.
766| * @returns {string} The rendered chunk (possibly blank when sections are empty).
767| ***/
768|function renderCustomLayoutChunk(
769|	chunk,
770|	sectionMap = {},
771|	interpolationContext = {},
772|) {
773|	const sections =
774|		sectionMap && typeof sectionMap === "object" ? sectionMap : {};
775|	const context =
776|		interpolationContext && typeof interpolationContext === "object"
777|			? interpolationContext
778|			: {};
779|	const rendered = [];
780|	const pattern = /\{\{([^}]+)\}\}/g;
781|	let cursor = 0;
782|	for (const match of String(chunk).matchAll(pattern)) {
783|		const name = String(match[1] || "").trim();
784|		if (!SECTION_TOKENS.includes(name)) continue;
785|		rendered.push(
786|			interpolatePromptKeywords(String(chunk).slice(cursor, match.index), context),
787|		);
788|		const block = sections[name];
789|		rendered.push(block === undefined || block === null ? "" : String(block));
790|		cursor = match.index + match[0].length;
791|	}
792|	rendered.push(
793|		interpolatePromptKeywords(String(chunk).slice(cursor), context),
794|	);
795|	return rendered.join("");
796|}
