798|/***
799| * MARK: renderCustomLayout
800| * @description Renders a custom layout: per-chunk section substitution with
801| *   prose interpolation, dropping chunks left blank by empty sections.
802| * @example renderCustomLayout('{{task}}\n\n{{stage}}', { task: 'a', stage: 'b' }) => 'a\n\nb'
803| * @param {string} layout - Custom layout markdown.
804| * @param {Object} [sectionMap] - Section name to pre-built block text.
805| * @param {Object} [interpolationContext] - Live keyword context.
806| * @returns {string} The rendered markdown.
807| ***/
808|function renderCustomLayout(
809|	layout,
810|	sectionMap = {},
811|	interpolationContext = {},
812|) {
813|	return String(layout)
814|		.split(/\n\s*\n/)
815|		.map((chunk) =>
816|			renderCustomLayoutChunk(chunk, sectionMap, interpolationContext),
817|		)
818|		.filter((chunk) => chunk.trim())
819|		.join("\n\n");
820|}
