822|export class PromptCurationEngine {
823|	/***
824|	 * MARK: constructor
825|	 * @description Creates the engine. All parameters are optional test seams:
826|	 *   `loadSkill` overrides skill lookup (`(name, projectCwd) => descriptor|null`),
827|	 *   `skillsMaxChars` overrides the injection size cap, `logger` receives
828|	 *   info/warn events for custom-layout renders, `promptLayoutDir` overrides
829|	 *   the layout state dir. Defaults come from the process-wide skills
830|	 *   registry and config, keeping legacy behaviour untouched.
831|	 * @param {Object} [opts]
832|	 * @param {Function} [opts.loadSkill]
833|	 * @param {number} [opts.skillsMaxChars]
834|	 * @param {Object} [opts.logger]
