836|	 ***/
837|	constructor({ loadSkill, skillsMaxChars, logger, promptLayoutDir } = {}) {
838|		this._loadSkillOverride = typeof loadSkill === "function" ? loadSkill : null;
839|		this._skillsMaxChars =
840|			typeof skillsMaxChars === "number" && skillsMaxChars > 0
