710|			if (!fenceChar) fenceChar = char;
711|			else if (char === fenceChar) fenceChar = "";
712|			continue;
713|		}
714|		if (!terminators.has(trimmed)) continue;
715|		if (firstRawTerminator < 0) firstRawTerminator = i;
716|		if (!fenceChar) {
717|			end = i;
718|			break;
719|		}
720|	}
