{"command":"node --input-type=module -e "
import fs from 'node:fs';
import { PromptCurationEngine } from './api/promptCuration.js';
const cwd = process.cwd();
for (const taskId of ['0d29c64c-34f5-4740-ba25-f4e6ef4f90b5','4f927ecb-ba3a-423c-ace3-5f7dd7d36896']) {
  const phantoms = taskId.startsWith('0d29')
    ? ['idea-20261115-222653.md','review-plan-20261115-223714.md','automated-tests-failure-20261115-233558.md','final-review-20261116-064824.md']
    : ['idea-20261116-072137.md','automated-tests-failure-20261116-102541.md'];
  const engine = new PromptCurationEngine();
  const prompt = engine.curatePrompt(
    { id: taskId, goal: 'G', reports: phantoms.map(f=>({path:\`./docs/tasks/\${taskId}/\${f}\`,filename:f})) },
    { id:'s', name:'Retrospective', prompt:'P' },
    { projectCwd: cwd, previousReports: phantoms.map(f=>\`./docs/tasks/\${taskId}/\${f}\`) }
  );
  const section = prompt.split('# Previous Reports')[1]?.split('\n\n')[0] || '';
  console.log('=== TASK '+taskId+' ===');
  console.log(section);
  const lines = section.split('\n').filter(l=>l.startsWith('- ./'));
  let ok=true;
  for (const l of lines) {
    const rel = l.replace(/^-\s*/,'').trim();
    const exists = fs.existsSync(rel);
    console.log((exists?'OPEN-OK ':'MISSING! ')+rel);
    if(!exists) ok=false;
  }
  for (const p of phantoms) {
    if (prompt.includes(p)) { console.log('PHANTOM-LEAKED: '+p); ok=false; }
  }
  const diskFiles = fs.readdirSync(\`docs/tasks/\${taskId}\`).filter(f=>f!=='task.md');
  console.log('disk files: '+diskFiles.join(','));
  console.log('listed count: '+lines.length+' overflow? '+section.includes('more files'));
  console.log(ok?'RESULT: PASS':'RESULT: FAIL');
}
