1|import { spawn } from "node:child_process";
2|import { withRepoGitLock } from "../work/gitLock.js";
3|import { isGitLockError } from "../work/taskErrors.js";
4|import { maybeRecoverStaleLock, _withLockCheckSuffix } from "./staleLock.js";
5|import { GitError } from "./errors.js";
6|const MAX_CAPTURE_BYTES = 1024 * 1024; // 1 MB per stream, defensive cap.
7|
8|/***
9| * MARK: git
10| * @description Runs a git command in the given working directory using an argv
11| *   array (never a shell string). Resolves { stdout, stderr, code } on exit 0
12| *   and rejects with a GitError otherwise. Streams are capped defensively and
13| *   the child receives an explicit timeout so a wedged git process cannot hang
14| *   a stage forever.
15| * @example const { stdout } = await git(cwd, ["rev-parse", "--abbrev-ref", "HEAD"]);
16| * @param {string} projectCwd - Working directory for the command.
17| * @param {string[]} args - Argument array (e.g. ["status", "--porcelain"]).
18| * @param {Object} [opts]
19| * @param {number} [opts.timeout=60000] - Hard timeout in milliseconds.
20| * @param {Function} [opts.listLiveGitProcesses] - Holder-scan override for the
21| *   stale-lock check (tests only: the holder scan is machine-global, so an
22| *   integration test asserting recovery must stub "no live holder" to stay
23| *   deterministic under parallel workers spawning their own git processes).
24| *   Production callers omit it and always get the real machine-wide scan.
25| * @param {Object} [opts.env] - Extra environment for the child (merged over
26| *   process.env), e.g. `{ GIT_INDEX_FILE: tmp }` for scratch-index plumbing.
27| * @returns {Promise<{stdout: string, stderr: string, code: number}>}
28| ***/
29|export function git(
30|	projectCwd,
31|	args,
32|	{ timeout = 60000, listLiveGitProcesses, env } = {},
33|) {
34|	if (typeof projectCwd !== "string" || !projectCwd.trim()) {
35|		return Promise.reject(new GitError("git requires a working directory"));
36|	}
37|	// `timeout: null` disables ...
38|	const effectiveTimeout =
39|		typeof timeout === "number" && Number.isFinite(timeout) && timeout > 0 ? timeout : null;
40|
41|	if (!Array.isArray(args) || args.length === 0) {
42|		return Promise.reject(
43|			new GitError("git requires a non-empty argument array"),
44|		);
45|	}
46|	if (args.some((a) => typeof a !== "string")) {
47|		return Promise.reject(
48|			new GitError("git arguments must all be strings (no shell interpolation)"),
49|		);
50|	}
51|	// Single serialization gate: every engine git process — reads and
52|	// writes — runs under the per-repository mutex, so concurrent branch
53|	// operations (task creation, approvals, running stages) can never
54|	// overlap in time and collide on `.git/index.lock`. Reads are included
55|	// deliberately: `status` refreshes the index on dirty trees, the cost
56|	// is one fast local op, and the engine runs one task at a time anyway.
57|	return withRepoGitLock(projectCwd, async () => {
58|		try {
59|			return await _spawnGit(projectCwd, args, { timeout: effectiveTimeout, env });
60|		} catch (err) {
61|			if (!isGitLockError(err)) throw err;
62|			const recoveryOpts = {};
63|			if (listLiveGitProcesses) {
64|				recoveryOpts.listLiveGitProcesses = listLiveGitProcesses;
65|			}
66|			const recovery = await maybeRecoverStaleLock(projectCwd, recoveryOpts).catch(() => ({
67|				recovered: false,
68|				reason: "assess-failed",
69|			}));
70|			if (!recovery.recovered) {
71|				throw _withLockCheckSuffix(err, recovery);
72|			}
73|			try {
74|				return await _spawnGit(projectCwd, args, { timeout: effectiveTimeout, env });
75|			} catch (retryErr) {
76|				// The retry ran on a cleared lock and still failed: keep the
77|				// recovery evidence on the error so failure routing and logs
78|				// show the lock was cleared, not the cause.
79|				if (retryErr && typeof retryErr === "object") {
80|					retryErr.gitLockRecovery = {
81|						lockPath: recovery.lockPath,
82|						ageMs: recovery.ageMs,
83|					};
84|				}
85|				throw retryErr;
86|			}
87|		}
88|	});
