91|/***
92| * MARK: _spawnGit
93| * @description Low-level git child-process runner behind `git()`: spawns
94| *   `git` with an argv array, caps captured output at MAX_CAPTURE_BYTES per
95| *   stream, enforces a hard timeout (SIGKILL on expiry), and resolves or
96| *   rejects with a typed GitError. Never called directly by engine code —
97| *   always go through `git()` so the per-repo lock gate applies.
98| * @private
99| * @param {string} projectCwd - Working directory for the command.
100| * @param {string[]} args - Argument array for the git binary.
101| * @param {Object} [opts]
102| * @param {number} [opts.timeout=60000] - Hard timeout in milliseconds.
103| * @param {Object} [opts.env] - Extra environment merged over process.env.
104| * @returns {Promise<{stdout: string, stderr: string, code: number}>}
105| ***/
106|function _spawnGit(projectCwd, args, { timeout = 60000, env } = {}) {
107|	return new Promise((resolve, reject) => {
108|		const child = spawn("git", args, {
109|			cwd: projectCwd,
110|			env: env ? { ...process.env, ...env } : process.env,
111|		});
112|		let stdout = "";
113|		let stderr = "";
114|		let settled = false;
115|		let timer = null;
116|		if (typeof timeout === "number" && Number.isFinite(timeout) && timeout > 0) {
117|			timer = setTimeout(() => {
118|				if (settled) return;
119|				settled = true;
120|				try {
121|					child.kill("SIGKILL");
122|				} catch {
123|					// already gone
124|				}
125|				// Kill-path hygiene: a SIGKILLed git can orphan `.git/index.lock`,
126|				// but ownership is unknowable here, so no eager deletion. The next
127|				// gated op re-assesses the lock via maybeRecoverStaleLock (age +
128|				// live-holder check) and recovers only provably stale locks.
129|				reject(
130|					new GitError(`git ${args.join(" ")} timed out after ${timeout}ms`, {
131|						args,
132|						stdout,
133|						stderr,
134|					}),
135|				);
136|			}, timeout);
137|			if (timer && timer.unref) timer.unref();
138|		}
139|
140|
141|		child.stdout?.on("data", (d) => {
142|			if (stdout.length < MAX_CAPTURE_BYTES) stdout += d.toString();
143|		});
144|		child.stderr?.on("data", (d) => {
145|			if (stderr.length < MAX_CAPTURE_BYTES) stderr += d.toString();
146|		});
147|		child.on("error", (err) => {
148|			if (settled) return;
149|			settled = true;
150|			if (timer) clearTimeout(timer);
151|			reject(
152|				new GitError(`Failed to start git: ${err.message} (is git installed?)`, {
153|					args,
154|					stderr: err.message,
155|				}),
156|			);
157|		});
