159|			if (settled) return;
160|			settled = true;
161|			if (timer) clearTimeout(timer);
162|			// Trim trailing whitespace/newlines only: stripping LEADING whitespace
163|			// would corrupt `git status --porcelain` v1 output, where the first
164|			// entry's status column (e.g. ' M') is significant.
165|			if (code === 0) {
166|				resolve({
167|					stdout: stdout.replace(/\s+$/, ""),
168|					stderr: stderr.replace(/\s+$/, ""),
169|					code,
170|				});
171|			} else {
172|				reject(
173|					new GitError(
174|						`git ${args.join(" ")} failed (exit ${code ?? signal ?? "unknown"}): ${stderr.trim() || stdout.trim() || "no output"}`,
175|						{ code, args, stdout, stderr },
176|					),
177|				);
178|			}
179|		});
180|	});
